  "message-scroller": [
    {
      "name": "message-scroller-demo",
      "title": "Default",
      "export": "MessageScrollerDemo",
      "lead": ""
    },
    {
      "name": "message-scroller-anchoring",
      "title": "Anchoring Turns",
      "export": "MessageScrollerAnchoring",
      "lead": "A turn is the part of the conversation that starts a new exchange. In a simple AI chat, that is usually the user's message and the assistant reply that follows."
    },
    {
      "name": "message-scroller-group-chat",
      "title": "Group Chat",
      "export": "MessageScrollerGroupChat",
      "lead": "In a group chat, the turn boundary is more specific than \"the user message\". It is often the message that asks the model to respond, or a marker like \"Marcus joined the chat\". Typing indicators and history controls usually should not anchor."
    },
    {
      "name": "message-scroller-previous-context",
      "title": "Keeping Context Visible",
      "export": "MessageScrollerPreviousContext",
      "lead": "When a new turn starts, it should still feel like part of the same continuous thread. scrollPreviousItemPeek keeps a slice of the previous item visible above the anchor, so the reader keeps their context instead of feeling like the conversation restarted on a blank page."
    },
    {
      "name": "message-scroller-streaming",
      "title": "Following the Live Edge",
      "export": "MessageScrollerStreaming",
      "lead": "When the reader is at the live edge, either because they stayed there or returned there, autoScroll keeps streamed replies in view as they grow. Scrolling away from the live edge releases the view, whether by wheel, touch, keyboard scroll keys, or dragging the scrollbar. An explicit message jump releases it too. New chunks can then arrive without moving the reader."
    },
    {
      "name": "message-scroller-opening-position",
      "title": "Opening Saved Threads",
      "export": "MessageScrollerOpeningPosition",
      "lead": "It can seem reasonable to reopen a saved thread at the absolute end of the transcript, but that often drops the reader into the conversation without enough context. A better default is \"last-anchor\": show the last meaningful turn, like the user's latest message, with the reply below it."
    },
    {
      "name": "message-scroller-load-history",
      "title": "Loading Earlier Messages",
      "export": "MessageScrollerLoadHistory",
      "lead": "Loading earlier messages should not move the conversation the reader is already looking at. When older rows are prepended above the current transcript,"
    },
    {
      "name": "message-scroller-animation",
      "title": "Animating New Messages",
      "export": "MessageScrollerAnimation",
      "lead": "A common chat pattern is to animate the user's message when it is sent, then let the assistant reply stream into a regular row below it. Start the user row below its final position so it feels like it rises from the live edge of the viewport."
    },
    {
      "name": "message-scroller-commands",
      "title": "Jumping to Messages",
      "export": "MessageScrollerCommands",
      "lead": "Search results, permalinks, outline items, and toolbar buttons often need to drive the transcript from outside the message list. Use useMessageScroller for those controls. Because the hooks read from MessageScrollerProvider, they work in any component inside the provider, including controls rendered outside the"
    },
    {
      "name": "message-scroller-visibility",
      "title": "Tracking the Reader's Position",
      "export": "MessageScrollerVisibility",
      "lead": "Use useMessageScrollerVisibility to track the reader's position in the conversation. A common example is a table-of-contents or a jump menu that highlights the current anchored turn."
    },
    {
      "name": "message-scroller-scrollable",
      "title": "Reading Scroll State",
      "export": "MessageScrollerScrollable",
      "lead": "Use useMessageScrollerScrollable when you need scroll state in JavaScript, such as a status indicator or a custom \"jump to latest\" control. It reports which edges the viewport can still scroll toward; \"at the start/end\" is the negation (!start / !end), and \"scrollable at all\" is start || end. For styling the scroller itself, prefer the data-scrollable attribute."
    }
  ],
